package com.enterprise.licensing.server;
import static org.assertj.core.api.Assertions.assertThat;import java.nio.file.Path;import java.util.UUID;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.ApplicationContext;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.NONE)class LicenseServerContextTest{private static final Path ROOT=Path.of(System.getProperty("java.io.tmpdir"),"license-server-context-"+UUID.randomUUID());@DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("licensing.data-file",()->ROOT.resolve("license.db").toString());r.add("licensing.identity-directory",()->ROOT.resolve("identity").toString());r.add("licensing.admin-token",()->"test-admin-token");}@Autowired ApplicationContext context;@Test void startsLocallyWithoutVendorConnectivityOrExternalDatabase(){assertThat(context.getBean(LicenseServerApplication.class)).isNotNull();}}
